def enforce_caps(weights: dict[str, float], meta: dict[str, NameMeta], caps: RiskCaps) -> CapOutcome:
    """Clip weights in place-copies. Cash is the residual and is unconstrained."""
    original = {ticker: max(0.0, float(weight)) for ticker, weight in weights.items() if weight}
    adjusted = dict(original)
    violations: list[dict[str, str]] = []

    for ticker, weight in original.items():
        if ticker not in meta:
            continue
        limit = _name_cap(meta[ticker], caps)
        if weight > limit + 1e-9:
            violations.append(
                {
                    "code": "single_name",
                    "ticker": ticker,
                    "detail": f"{ticker} weight {weight:.4f} exceeds {limit:.4f}",
                }
            )

    sectors: dict[str, float] = defaultdict(float)
    for ticker, weight in original.items():
        if ticker in meta:
            sectors[meta[ticker].sector] += weight
    for sector, total in sectors.items():
        if sector and total > caps.sector_pct + 1e-9:
            violations.append(
                {
                    "code": "sector",
                    "ticker": sector,
                    "detail": f"{sector} weight {total:.4f} exceeds {caps.sector_pct:.4f}",
                }
            )

    sleeve_total = sum(weight for ticker, weight in original.items() if ticker in meta and _in_sleeve(meta[ticker], caps))
    if sleeve_total > caps.high_risk_sleeve_pct + 1e-9:
        violations.append(
            {
                "code": "high_risk_sleeve",
                "ticker": "*",
                "detail": f"high-risk sleeve {sleeve_total:.4f} exceeds {caps.high_risk_sleeve_pct:.4f}",
            }
        )

    penny_total = sum(
        weight
        for ticker, weight in original.items()
        if ticker in meta and meta[ticker].price < caps.penny_price_threshold
    )
    if penny_total > caps.penny_total_pct + 1e-9:
        violations.append(
            {
                "code": "penny_total",
                "ticker": "*",
                "detail": f"penny sleeve {penny_total:.4f} exceeds {caps.penny_total_pct:.4f}",
            }
        )

    for _ in range(4):
        for ticker in list(adjusted):
            if ticker not in meta:
                continue
            limit = _name_cap(meta[ticker], caps)
            if adjusted[ticker] > limit:
                adjusted[ticker] = limit
        by_sector: dict[str, list[str]] = defaultdict(list)
        for ticker in adjusted:
            if ticker in meta:
                by_sector[meta[ticker].sector].append(ticker)
        for tickers in by_sector.values():
            total = sum(adjusted[ticker] for ticker in tickers)
            if total > caps.sector_pct + 1e-12:
                scale = caps.sector_pct / total
                for ticker in tickers:
                    adjusted[ticker] *= scale
        sleeve_names = [ticker for ticker in adjusted if ticker in meta and _in_sleeve(meta[ticker], caps)]
        total = sum(adjusted[ticker] for ticker in sleeve_names)
        if total > caps.high_risk_sleeve_pct + 1e-12:
            scale = caps.high_risk_sleeve_pct / total
            for ticker in sleeve_names:
                adjusted[ticker] *= scale
        penny_names = [
            ticker for ticker in adjusted if ticker in meta and meta[ticker].price < caps.penny_price_threshold
        ]
        total = sum(adjusted[ticker] for ticker in penny_names)
        if total > caps.penny_total_pct + 1e-12:
